<?php
declare(strict_types=1);require_once __DIR__.'/includes/header.php';
$releaseId=sanitize($_GET['release_id']??'');$release=$releaseId?release_by_id($releaseId):current_release();if(!$release || !($release['is_published']??false)){http_response_code(404);fail('The requested release is not available or has been removed.');}
$filename=safe_filename((string)($release['filename']??''));$source=config_path('browsers').'/'.$filename;if(!is_file($source)||!is_readable($source)){http_response_code(404);fail('The installer file is temporarily unavailable.');}
$expectedChecksum=(string)($release['checksum']??'');if($expectedChecksum!==''&&sha256_file($source)!==$expectedChecksum){http_response_code(500);fail('The installer checksum does not match the release metadata.');}
$record=['id'=>bin2hex(random_bytes(16)),'release_id'=>$release['id'],'user_id'=>current_user()['id']??null,'operating_system'=>'Windows','architecture'=>(string)($release['architecture']??'64-bit'),'downloaded_at'=>date('c'),'ip_hash'=>ips_hash($_SERVER['REMOTE_ADDR']??'unknown'),'filename'=>$filename];if(!append_json('downloads.json',$record)){fail('The download could not be recorded.',500);}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$filename.'"');$fileSize=filesize($source);if($fileSize===false){fail('The installer size could not be determined.',500);}header('Content-Length: '.$fileSize);header('X-Content-Type-Options: nosniff');readfile($source);exit;
